// Unity translation unit for cpp2lean: the MAVLink C library of the reference build, generated by
// ardupilot/gen_unity_mavlink.py (do not edit; README.md, "Phase 4: the MAVLink C library"). ArduPilot's
// GCS_MAVLink.h and the generated mavlink_helpers.h are included unmodified, as GCS_MAVLink.cpp includes
// them (ardupilot/translate_mavlink.sh checks that they preprocess here as in GCS_MAVLink.cpp's own unit).
#include <AP_HAL/AP_HAL.h>
#include <GCS_MAVLink/GCS_config.h>
#include <GCS_MAVLink/GCS_MAVLink.h>
#include <GCS_MAVLink/include/mavlink/v2.0/mavlink_helpers.h>

// ---- stand-ins for what GCS_MAVLink.cpp and GCS_MAVLINK provide around the library (not protocol code) ----

// the parse buffer and status of each channel (GCS_MAVLINK::_channel_buffer/_channel_status of the link on
// that channel, which mavlink_get_channel_buffer/status return, GCS_MAVLink.cpp:42-64)
static mavlink_message_t mav_chan_buffer[MAVLINK_COMM_NUM_BUFFERS];
static mavlink_status_t mav_chan_status[MAVLINK_COMM_NUM_BUFFERS];

mavlink_message_t* mavlink_get_channel_buffer(uint8_t chan) { return &mav_chan_buffer[chan]; }
mavlink_status_t* mavlink_get_channel_status(uint8_t chan) { return &mav_chan_status[chan]; }

// GCS_MAVLink.cpp:83
mavlink_system_t mavlink_system = {7,1};

// the UART bytes: comm_send_buffer appends what the library sends to one queue (the reference's
// comm_send_buffer writes mavlink_comm_port[chan], GCS_MAVLink.cpp:168-190); the channel is not recorded,
// the tests send on one channel at a time
static uint8_t mav_uart[2048];
static uint16_t mav_uart_len;

void comm_send_buffer(mavlink_channel_t chan, const uint8_t *buf, uint8_t len)
{
    for (uint8_t i = 0; i < len; i++) {
        if (mav_uart_len < sizeof(mav_uart)) {
            mav_uart[mav_uart_len++] = buf[i];
        }
    }
}

// ---- the test functions (harness) ----

// every test starts from the same state on both sides (the C++ keeps file-scope state between calls)
static void mav_reset()
{
    for (uint8_t c = 0; c < MAVLINK_COMM_NUM_BUFFERS; c++) {
        memset(&mav_chan_buffer[c], 0, sizeof(mav_chan_buffer[c]));
        memset(&mav_chan_status[c], 0, sizeof(mav_chan_status[c]));
    }
    mavlink_system.sysid = 7;
    mavlink_system.compid = 1;
    mav_uart_len = 0;
}

static uint32_t rnd(uint32_t *s)
{
    uint32_t x = *s;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    *s = x;
    return x;
}

// small values, the extremes, or any value
static uint32_t gen_u32(uint32_t *s)
{
    const uint32_t k = rnd(s) % 8;
    if (k == 0) {
        return rnd(s) % 4;
    }
    if (k == 1) {
        return 0xffffffffU - rnd(s) % 3;
    }
    return rnd(s);
}

static uint64_t gen_u64(uint32_t *s)
{
    const uint64_t hi = gen_u32(s);
    return (hi << 32) | rnd(s);
}

// a system id: mostly 8-bit, sometimes wider (SYSID32, TARGET32 headers)
static uint32_t gen_sysid(uint32_t *s)
{
    const uint32_t k = rnd(s) % 8;
    if (k == 0) {
        return 256 + rnd(s) % 1000;
    }
    if (k == 1) {
        return rnd(s);
    }
    return rnd(s) % 256;
}

// a character: often zero (strings end anywhere), letters, any byte
static char gen_char(uint32_t *s)
{
    const uint32_t k = rnd(s) % 8;
    if (k == 0) {
        return 0;
    }
    if (k < 5) {
        return (char)(65 + rnd(s) % 26);
    }
    return (char)rnd(s);
}

// a float: special values (NaN with payloads, infinities, -0, denormals) or any bit pattern
static float gen_f32(uint32_t *s)
{
    uint32_t u = rnd(s);
    const uint32_t k = rnd(s) % 16;
    if (k == 0) {
        u = 0x7f800000U | (rnd(s) & 0x807fffffU) | 1U;
    } else if (k == 1) {
        u = (rnd(s) & 0x80000000U) | 0x7f800000U;
    } else if (k == 2) {
        u = rnd(s) & 0x807fffffU;
    } else if (k == 3) {
        u = 0x80000000U;
    }
    float f;
    memcpy(&f, &u, sizeof(f));
    return f;
}

static double gen_f64(uint32_t *s)
{
    uint64_t u = gen_u64(s);
    if (rnd(s) % 8 == 0) {
        u = 0x7ff0000000000001ULL | (u & 0x800fffffffffffffULL);
    }
    double d;
    memcpy(&d, &u, sizeof(d));
    return d;
}

static uint64_t hash_u64(uint64_t h, uint64_t v)
{
    for (uint8_t i = 0; i < 8; i++) {
        h = (h ^ (uint8_t)(v >> (8 * i))) * 1099511628211ULL;
    }
    return h;
}

static uint64_t hash_f32(uint64_t h, float f)
{
    uint32_t u;
    memcpy(&u, &f, sizeof(u));
    return hash_u64(h, u);
}

static uint64_t hash_f64(uint64_t h, double d)
{
    uint64_t u;
    memcpy(&u, &d, sizeof(u));
    return hash_u64(h, u);
}

static uint64_t hash_bytes(uint64_t h, const uint8_t *b, uint16_t n)
{
    for (uint16_t i = 0; i < n; i++) {
        h = (h ^ b[i]) * 1099511628211ULL;
    }
    return h;
}

// the header fields of a message
static uint64_t hash_head(uint64_t h, const mavlink_message_t *m)
{
    h = hash_u64(h, m->checksum);
    h = hash_u64(h, m->magic);
    h = hash_u64(h, m->len);
    h = hash_u64(h, m->incompat_flags);
    h = hash_u64(h, m->compat_flags);
    h = hash_u64(h, m->seq);
    h = hash_u64(h, m->sysid);
    h = hash_u64(h, m->compid);
    h = hash_u64(h, m->msgid);
    h = hash_u64(h, m->target_sysid);
    return h;
}

// every field of a message: the header, the whole payload buffer, the checksum bytes, the signature
static uint64_t hash_msg(uint64_t h, const mavlink_message_t *m)
{
    h = hash_head(h, m);
    h = hash_bytes(h, (const uint8_t *)_MAV_PAYLOAD(m), MAVLINK_MAX_PAYLOAD_LEN + MAVLINK_NUM_CHECKSUM_BYTES + 7);
    h = hash_bytes(h, m->ck, 2);
    h = hash_bytes(h, m->signature, MAVLINK_SIGNATURE_BLOCK_LEN);
    return h;
}

static uint64_t hash_status(uint64_t h, const mavlink_status_t *st)
{
    h = hash_u64(h, st->msg_received);
    h = hash_u64(h, st->buffer_overrun);
    h = hash_u64(h, st->parse_error);
    h = hash_u64(h, (uint32_t)st->parse_state);
    h = hash_u64(h, st->packet_idx);
    h = hash_u64(h, st->current_rx_seq);
    h = hash_u64(h, st->current_tx_seq);
    h = hash_u64(h, st->packet_rx_success_count);
    h = hash_u64(h, st->packet_rx_drop_count);
    h = hash_u64(h, st->flags);
    h = hash_u64(h, st->signature_wait);
    return h;
}

// the channel set up for a test: MAVLink 1 or 2 out, a sequence number, the same on all four channels
static void chan_setup(uint32_t *s, uint8_t mav1)
{
    const uint8_t seq = (uint8_t)rnd(s);
    for (uint8_t c = 0; c < 4; c++) {
        mav_chan_status[c].flags = mav1 ? MAVLINK_STATUS_FLAG_OUT_MAVLINK1 : 0;
        mav_chan_status[c].current_tx_seq = seq;
    }
}

// crc_calculate, crc_accumulate_buffer and crc_accumulate on random bytes
uint64_t crc_buf(uint32_t seed, uint8_t n)
{
    uint32_t st = seed | 1;
    uint8_t b[256];
    for (uint16_t i = 0; i < 256; i++) {
        b[i] = (uint8_t)rnd(&st);
    }
    uint16_t c = crc_calculate(b, n);
    crc_accumulate_buffer(&c, (const char *)b, (uint16_t)(n / 2));
    crc_accumulate(b[n], &c);
    return c;
}

// mavlink_get_msg_entry: the table's binary search, for ids in and out of the table
uint64_t msg_entry(uint32_t msgid)
{
    const mavlink_msg_entry_t *e = mavlink_get_msg_entry(msgid);
    if (e == NULL) {
        return 0xffffffffffffffffULL;
    }
    uint64_t h = 1469598103934665603ULL;
    h = hash_u64(h, e->msgid);
    h = hash_u64(h, e->crc_extra);
    h = hash_u64(h, e->min_msg_len);
    h = hash_u64(h, e->max_msg_len);
    h = hash_u64(h, e->flags);
    h = hash_u64(h, e->target_system_ofs);
    h = hash_u64(h, e->target_component_ofs);
    return h;
}

// ---- HEARTBEAT (minimal/mavlink_msg_heartbeat.h) ----

uint64_t pk_heartbeat(uint32_t seed, uint8_t mode_)
{
    uint32_t st = seed | 1;
    mav_reset();
    chan_setup(&st, mode_ & 1);
    const uint8_t chan = (uint8_t)(rnd(&st) % 4);
    const uint32_t sysid = gen_sysid(&st);
    const uint8_t compid = (uint8_t)rnd(&st);
    const uint8_t type = rnd(&st) % 4 == 0 ? (uint8_t)0 : (uint8_t)rnd(&st);
    const uint8_t autopilot = rnd(&st) % 4 == 0 ? (uint8_t)0 : (uint8_t)rnd(&st);
    const uint8_t base_mode = rnd(&st) % 4 == 0 ? (uint8_t)0 : (uint8_t)rnd(&st);
    const uint32_t custom_mode = rnd(&st) % 4 == 0 ? (uint32_t)0 : gen_u32(&st);
    const uint8_t system_status = rnd(&st) % 4 == 0 ? (uint8_t)0 : (uint8_t)rnd(&st);
    mavlink_message_t msg;
    memset(&msg, 0, sizeof(msg));
    uint16_t n = 0;
    const uint8_t api = (mode_ >> 1) % 4;
    if (api == 0) {
        n = mavlink_msg_heartbeat_pack(sysid, compid, &msg, type, autopilot, base_mode, custom_mode, system_status);
    } else if (api == 1) {
        n = mavlink_msg_heartbeat_pack_chan(sysid, compid, chan, &msg, type, autopilot, base_mode, custom_mode, system_status);
    } else {
        mavlink_heartbeat_t pkt;
        memset(&pkt, 0, sizeof(pkt));
        pkt.type = type;
        pkt.autopilot = autopilot;
        pkt.base_mode = base_mode;
        pkt.custom_mode = custom_mode;
        pkt.system_status = system_status;
        if (api == 2) {
            n = mavlink_msg_heartbeat_encode(sysid, compid, &msg, &pkt);
        } else {
            n = mavlink_msg_heartbeat_encode_chan(sysid, compid, chan, &msg, &pkt);
        }
    }
    uint8_t buf[MAVLINK_MAX_PACKET_LEN];
    memset(buf, 0, sizeof(buf));
    const uint16_t len = mavlink_msg_to_send_buffer(buf, &msg);
    uint64_t h = 1469598103934665603ULL;
    h = hash_u64(h, n);
    h = hash_u64(h, len);
    h = hash_bytes(h, buf, len);
    h = hash_msg(h, &msg);
    h = hash_status(h, &mav_chan_status[chan]);
    h = hash_status(h, &mav_chan_status[0]);
    return h;
}

