uint64_t dc_heartbeat(uint32_t seed, uint8_t len, uint8_t flags)
{
    uint32_t st = seed | 1;
    mav_reset();
    mavlink_message_t msg;
    memset(&msg, 0, sizeof(msg));
    for (uint16_t i = 0; i < MAVLINK_MAX_PAYLOAD_LEN + MAVLINK_NUM_CHECKSUM_BYTES + 7; i++) {
        _MAV_PAYLOAD_NON_CONST(&msg)[i] = (char)(rnd(&st) % 4 == 0 ? 0 : rnd(&st));
    }
    msg.len = len % 2 ? len % (MAVLINK_MSG_ID_HEARTBEAT_LEN + 1) : len;
    msg.msgid = MAVLINK_MSG_ID_HEARTBEAT;
    msg.incompat_flags = flags;
    msg.target_sysid = gen_sysid(&st);
    mavlink_heartbeat_t pkt;
    memset(&pkt, 0, sizeof(pkt));
    mavlink_msg_heartbeat_decode(&msg, &pkt);
    uint64_t h = 1469598103934665603ULL;
    h = hash_bytes(h, (const uint8_t *)&pkt, sizeof(pkt));
    h = hash_u64(h, mavlink_msg_heartbeat_get_type(&msg));
    h = hash_u64(h, mavlink_msg_heartbeat_get_autopilot(&msg));
    h = hash_u64(h, mavlink_msg_heartbeat_get_base_mode(&msg));
    h = hash_u64(h, mavlink_msg_heartbeat_get_custom_mode(&msg));
    h = hash_u64(h, mavlink_msg_heartbeat_get_system_status(&msg));
    h = hash_u64(h, mavlink_msg_heartbeat_get_mavlink_version(&msg));
    return h;
}

