    const uint32_t target_system = rnd(&st) % 4 == 0 ? 0 : gen_sysid(&st);
    const uint8_t target_component = rnd(&st) % 4 == 0 ? (uint8_t)0 : (uint8_t)rnd(&st);
    char param_id[16];
    const bool param_id_zero = rnd(&st) % 4 == 0;
